import RegistrationForm from './component'
import { useEffect, useState } from 'react'
import {
  useGetCustomerTravelDetails,
  useGetTravelDetails,
  useUpdateTravelDraft,
  useUpdateCustomerTravelDraft,
  useUpdateTravelSaveDraft,
} from '../../state/hooks/useTravelState'
import isEmpty from 'lodash/isEmpty'
import { Loader, Container as ComponentContainer } from '../../../../../components'
import {
  resetError,
  useErrorContextValue,
  useLoaderContextValue,
} from '@pasarpolis/common-react-hooks'
import { LANG_STRINGS } from '../../../../../lang'
import ShowSnackbar from '../../../../../components/ShowNotification'
import { useHistory, useParams } from 'react-router'
import PolicyStepsHeader from '../../../../../components/PolicyStepsHeader'
import { TRAVEL_STEPS } from '../../constant'
import PackageNotFound from '../../../Packages/components/PackageNotFound'
import get from 'lodash/get'
import { useUpdateGlobal } from '../../../../../state/globalState/hooks/useGlobalContext'
import UploadTravel from './UploadTravel'
import TravelUploadModeButton from '../../components/TravelUploadModeButton'
import { ERROR_DUPLICATE_FIELD } from './constants'

function Container() {
  const { draftId: draftQuoteId } = useParams()
  const [{ globalState: { isLoggedIn } = {} }] = useUpdateGlobal()
  const [{ getTravelDetailsData = {} }, getTravelDetailsRequest] = useGetTravelDetails()
  const [{ updateTravelDraftData = {} }, updateTravelDraftRequest] = useUpdateTravelDraft()
  const [{ updateCustomerDraftQuoteData = {} }, updateCustomerTravelDraftRequest] =
    useUpdateCustomerTravelDraft()
  const [{ getCustomerDraftQuoteDetailData = {} }, getCustomerDraftQuoteDetailRequest] =
    useGetCustomerTravelDetails()
  const [, updateTravelSaveDraftRequest] = useUpdateTravelSaveDraft()
  const [
    {
      GET_TRAVEL_DETAILS_LOADER,
      UPDATE_TRAVEL_DRAFT_LOADER,
      GET_CUSTOMER_DRAFT_QUOTE_DETAIL_LOADER,
    },
  ] = useLoaderContextValue()
  // 1 main traveller + additional member count
  const passangerTotal =
    get(getTravelDetailsData, 'policy_details.additional_member_count.total', 0) + 1
  const [
    {
      GET_TRAVEL_DETAILS_ERROR,
      UPDATE_TRAVEL_DRAFT_ERROR,
      updateTravelDraftStatus,
      // updateCustomerTravelDraftStatus,
      GET_CUSTOMER_DRAFT_QUOTE_DETAIL_ERROR,
    },
    dispatchError,
  ] = useErrorContextValue()
  const history = useHistory()
  const [calledTimer] = useState(false)
  const [isModeUpload, setIsModeUpload] = useState(false)
  const handleBackClick = () => {
    history.push({
      pathname: `/travel/package_detail/${draftQuoteId}`,
    })
  }

  useEffect(() => {
    if (!isModeUpload) {
      if (isLoggedIn) {
        if (draftQuoteId) {
          getTravelDetailsRequest({ draftQuoteId })
        }
      } else {
        if (draftQuoteId) {
          getCustomerDraftQuoteDetailRequest({ draftQuoteId })
        }
      }
    }
  }, [isLoggedIn, draftQuoteId, isModeUpload])

  useEffect(() => {
    if (UPDATE_TRAVEL_DRAFT_ERROR && updateTravelDraftStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updateTravelDraftStatus,
      })
      dispatchError(
        resetError({
          updateTravelDraftStatus: '',
        })
      )
    }
  }, [UPDATE_TRAVEL_DRAFT_ERROR, updateTravelDraftStatus])

  useEffect(() => {
    // debugger
    if (isLoggedIn && !isEmpty(updateTravelDraftData)) {
      // debugger
      const { msg, success } = updateTravelDraftData
      if (success) {
        ShowSnackbar.success({
          visible: true,
          text: LANG_STRINGS.registrationSuccessful || msg,
        })
        dispatchError(
          resetError({
            updateTravelDraftStatus: '',
            getTravelDetailsStatus: '',
          })
        )
        history.push(`/travel/confirmation/${draftQuoteId}`)
      } else {
        ShowSnackbar.error({
          visible: true,
          text: 'error',
        })
      }
    }
    if (!isEmpty(updateCustomerDraftQuoteData)) {
      const { msg, success } = updateCustomerDraftQuoteData
      if (success) {
        ShowSnackbar.success({
          visible: true,
          text: LANG_STRINGS.registrationSuccessful || msg,
        })
        dispatchError(
          resetError({
            updateTravelDraftStatus: '',
            getTravelDetailsStatus: '',
          })
        )
        history.push(`/travel/confirmation/${draftQuoteId}`)
      } else {
        ShowSnackbar.error({
          visible: true,
          text: 'error',
        })
      }
    }
  }, [updateTravelDraftData, updateCustomerDraftQuoteData, isLoggedIn])

  useEffect(() => {
    if (passangerTotal > 10) {
      setIsModeUpload(true)
    }
  }, [passangerTotal])

  let { policy_details: policyDetails = {} } = getTravelDetailsData

  if (getCustomerDraftQuoteDetailData?.agent_info?.name) {
    policyDetails = getCustomerDraftQuoteDetailData.policy_details
  }

  // const { policy_details: policyDetails = {} } = getTravelDetailsData
  const {
    additional_member_count: additionalMemberCount = {},
    customer_data: customerData = {},
    start_date: travellingStartDate = '',
    travel_type: travelType = '',
    policy_type: policyType = '',
  } = policyDetails
  const {
    main_traveller: mainTraveller = {},
    adults: adultData = [],
    kids: kidsData = [],
  } = customerData
  const { total = 0 } = additionalMemberCount

  function checkDuplicates(data) {
    const primary = data.person
    const additional = data.additionalPerson
    const mobileNoSet = new Set()
    const emailSet = new Set()
    const insuredIdSet = new Set()

    function checkAndAdd(person, field, valueSet) {
      if (person[field]) {
        if (valueSet.has(person[field])) {
          ShowSnackbar.error({
            visible: true,
            text: `Terdapat Duplikat Pada ${ERROR_DUPLICATE_FIELD[field] ?? ''} : ${person[field]}`,
          })
          return true
        } else {
          valueSet.add(person[field])
          return false
        }
      } else return false
    }

    if (checkAndAdd(primary, 'mobile_no', mobileNoSet)) return true
    if (checkAndAdd(primary, 'email', emailSet)) return true
    if (checkAndAdd(primary, 'insured_id', insuredIdSet)) return true

    for (const person of additional) {
      if (checkAndAdd(person, 'mobile_no', mobileNoSet)) return true
      if (checkAndAdd(person, 'email', emailSet)) return true
      if (checkAndAdd(person, 'insured_id', insuredIdSet)) return true
    }
    return false
  }
  const submitTravelRegistrationData = (payload) => {
    if (checkDuplicates(payload)) return
    const mainTravellerCitizenship = get(payload, 'person.citizenship', '')

    const ktpType =
      travelType === 'international'
        ? 'passport'
        : travelType === 'domestic' && mainTravellerCitizenship === 'WNI'
          ? 'ktp'
          : travelType === 'domestic' && mainTravellerCitizenship === 'WNA'
            ? 'kitas'
            : ''
    // const adultsDataWithKTPType = Array.isArray(payload.adults) ? payload.adults.map((item) => ({ ...item, insured_id_type: ktpType })) : []
    const customerDetails = {
      main_traveller: {
        ...payload.person,
        insured_id_type: ktpType,
      },
      // adults: adultsDataWithKTPType,
      // kids: payload.children || [],
      ...payload.person,
      insured_id_type: ktpType,
      customer_address: {
        address: payload.person.address,
      },
      adults: [],
      kids: [],
      parents: [],
      siblings: [],
    }
    payload.additionalPerson.forEach((person) => {
      const { relation, insured_id: insuranceId, ...personData } = person
      if (insuranceId) {
        personData.insured_id = insuranceId
        personData.insured_id_type =
          travelType === 'international'
            ? 'passport'
            : personData?.citizenship === 'WNA'
              ? 'kitas'
              : 'ktp'
      }
      switch (person.relation) {
        case 'spouse':
          customerDetails.adults = customerDetails.adults
            ? [...customerDetails.adults, personData]
            : [personData]
          break
        case 'child':
          customerDetails.kids = customerDetails.kids
            ? [...customerDetails.kids, personData]
            : [personData]
          break
        case 'sibling':
          customerDetails.siblings = customerDetails.siblings
            ? [...customerDetails.siblings, personData]
            : [personData]
          break
        case 'parent':
          customerDetails.parents = customerDetails.parents
            ? [...customerDetails.parents, personData]
            : [personData]
          break
        default:
          customerDetails.adults = customerDetails.adults
            ? [...customerDetails.adults, personData]
            : [personData]
          break
      }
    })
    const updatedPolicyDetails = {
      ...policyDetails,
      additional_member_count: {
        ...policyDetails.additional_member_count,
        adult: customerDetails?.adults.length,
        kids: customerDetails?.kids.length,
        parents: customerDetails?.parents.length,
        siblings: customerDetails?.siblings.length,
      },
    }
    const payloadData = {
      body: {
        section: 'customer_data',
        sub_section: 'customer_document',
        data: {
          ...updatedPolicyDetails,

          customer_data: {
            ...customerDetails,
          },
        },
      },
      draftQuoteId,
    }
    if (isLoggedIn) {
      updateTravelDraftRequest(payloadData)
    } else {
      updateCustomerTravelDraftRequest(payloadData)
    }
  }

  const submitTravelRegistrationDraft = (payload) => {
    const mainTravellerCitizenship = get(payload, 'person.citizenship', '')

    const ktpType =
      travelType === 'international'
        ? 'passport'
        : travelType === 'domestic' && mainTravellerCitizenship === 'WNI'
          ? 'ktp'
          : travelType === 'domestic' && mainTravellerCitizenship === 'WNA'
            ? 'kitas'
            : ''
    // const adultsDataWithKTPType = Array.isArray(payload.adults) ? payload.adults.map((item) => ({ ...item, insured_id_type: ktpType })) : []
    const customerDetails = {
      main_traveller: {
        ...payload.person,
        insured_id_type: ktpType,
      },
      // adults: adultsDataWithKTPType,
      // kids: payload.children || [],
      ...payload.person,
      insured_id_type: ktpType,
      customer_address: {
        address: payload.person.address,
      },
      adults: [],
      kids: [],
      parents: [],
      siblings: [],
    }
    payload.additionalPerson.forEach((person) => {
      const { relation, insured_id: insuranceId, ...personData } = person
      if (insuranceId) {
        personData.insured_id = insuranceId
        personData.insured_id_type =
          travelType === 'international'
            ? 'passport'
            : personData?.citizenship === 'WNA'
              ? 'kitas'
              : 'ktp'
      }
      switch (person.relation) {
        case 'spouse':
          customerDetails.adults = customerDetails.adults
            ? [...customerDetails.adults, personData]
            : [personData]
          break
        case 'child':
          customerDetails.kids = customerDetails.kids
            ? [...customerDetails.kids, personData]
            : [personData]
          break
        case 'sibling':
          customerDetails.siblings = customerDetails.siblings
            ? [...customerDetails.siblings, personData]
            : [personData]
          break
        case 'parent':
          customerDetails.parents = customerDetails.parents
            ? [...customerDetails.parents, personData]
            : [personData]
          break
        default:
          customerDetails.adults = customerDetails.adults
            ? [...customerDetails.adults, personData]
            : [personData]
          break
      }
    })
    const updatedPolicyDetails = {
      ...policyDetails,
      additional_member_count: {
        ...policyDetails.additional_member_count,
        adult: customerDetails?.adults.length,
        kids: customerDetails?.kids.length,
        parents: customerDetails?.parents.length,
        siblings: customerDetails?.siblings.length,
      },
    }
    const payloadData = {
      body: {
        section: 'customer_data',
        sub_section: 'customer_document',
        data: {
          ...updatedPolicyDetails,

          customer_data: {
            ...customerDetails,
          },
        },
      },
      draftQuoteId,
    }
    if (isLoggedIn) {
      updateTravelSaveDraftRequest(payloadData)
    }
  }

  return (
    <ComponentContainer
      title={LANG_STRINGS.register}
      showInnerHeader
      displayBackButton
      hideBottomTabs
      onClose={() => history.replace('/dashboard')}
      showCloseIcon
      onBackClick={handleBackClick}
    >
      <PolicyStepsHeader
        stepsData={TRAVEL_STEPS}
        activeCount={3}
        prevActive={{ 1: true, 2: true }}
      />
      {!isModeUpload && policyType === 'group' && (
        <TravelUploadModeButton onChangeModeUpload={() => setIsModeUpload(true)} />
      )}
      <Loader
        visible={
          GET_TRAVEL_DETAILS_LOADER ||
          UPDATE_TRAVEL_DRAFT_LOADER ||
          GET_CUSTOMER_DRAFT_QUOTE_DETAIL_LOADER
        }
      />
      {GET_TRAVEL_DETAILS_ERROR || GET_CUSTOMER_DRAFT_QUOTE_DETAIL_ERROR ? (
        <PackageNotFound history={history} showProductBtn={false} />
      ) : null}
      {isEmpty(mainTraveller) ? null : isModeUpload ? (
        <UploadTravel
          onBackToManual={() => setIsModeUpload(false)}
          travelType={travelType}
          draftQuoteId={draftQuoteId}
          onUploadSuccess={() => getTravelDetailsRequest({ draftQuoteId })}
          onNextStep={() => history.push(`/travel/confirmation/${draftQuoteId}`)}
          passangerTotal={passangerTotal}
        />
      ) : (
        <RegistrationForm
          totalPeople={total}
          travelType={travelType}
          policyType={policyType}
          adultInitialValues={adultData}
          kidsInitialValues={kidsData}
          travellingStartDate={travellingStartDate}
          mainTravellerIntialValues={mainTraveller}
          customerData={customerData}
          submitTravelRegistrationData={submitTravelRegistrationData}
          submitTravelRegistrationDraft={submitTravelRegistrationDraft}
          calledTimer={calledTimer}
        />
      )}
    </ComponentContainer>
  )
}

export default Container
