import { TRAVEL_ACTIONS } from './actions'

const reducer = (state = TRAVEL_ACTIONS, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case TRAVEL_ACTIONS.GET_TRAVEL_REGION:
    case TRAVEL_ACTIONS.CREATE_TRAVEL_DRAFT:
    case TRAVEL_ACTIONS.UPDATE_TRAVEL_DRAFT:
    case TRAVEL_ACTIONS.GET_TRAVEL_DETAILS:
    case TRAVEL_ACTIONS.GET_PACKAGES:
    case TRAVEL_ACTIONS.GET_PACKAGES_DETAIL:
    case TRAVEL_ACTIONS.GET_COMPLETE_DRAFT:
    case TRAVEL_ACTIONS.UPDATE_TRAVEL_SAVE_DRAFT:
    case TRAVEL_ACTIONS.GET_CUSTOMER_DRAFT_QUOTE_DETAIL:
    case TRAVEL_ACTIONS.SHARE_DRAFT_QUOTE:
    case TRAVEL_ACTIONS.UPDATE_CUSTOMER_DRAFT_QUOTE:
    case TRAVEL_ACTIONS.GET_CUSTOMER_COMPLETE_DRAFT:
    case TRAVEL_ACTIONS.GET_DOWNLOAD_TRAVEL_DRAFT_PDF:
    case TRAVEL_ACTIONS.UPLOAD_TRAVEL_PASSENGER:
      return {
        ...state,
        ...payload,
      }
    default:
      return {
        ...(state || {}),
      }
  }
}

export default reducer
