import {
  GenderWrapper,
  Label,
  Option,
  OptionWrapper
} from './index.style'
import { LANG_STRINGS } from '../../../../lang'
import { useEffect } from 'react'

const options = [
  {
    title: LANG_STRINGS.male,
    value: 'male'
  },
  {
    title: LANG_STRINGS.female,
    value: 'female'
  }
]

function Gender (props) {
  const { label, onChange, value: selectedGender, defaultValue, disabled } = props

  useEffect(() => {
    if (defaultValue) {
      onChange(defaultValue)
    }
  }, [defaultValue])

  const onChangeHandler = (value) => {
    if (disabled) return
    onChange(value)
  }

  return (
    <GenderWrapper>
      <Label>
        {label}
      </Label>
      <OptionWrapper>

        {
          options.map(({ title, value }) => {
            return (
              <Option active={selectedGender === value} key={value} onClick={() => onChangeHandler(value)}>
                {title}
              </Option>
            )
          })
        }
      </OptionWrapper>

    </GenderWrapper>
  )
}

export default Gender
