import { LANG_STRINGS } from '../../../../../../lang'
import {
  getNameLabel,
  validateName,
  validateDateOfBirth,
  getFamilyRelationOptions,
  validateFamilyRelation,
  getInsuredIdLabel,
  validateInsuredId,
  getAddressLabel,
  validatePhoneNumber,
  validateEmail
} from './helpers'

export const personDetailsformData = ({ travellingStartDate, travelType, values }) => ({
  fieldData: [
    {
      label: getNameLabel({ travelType, values }),
      name: 'name',
      type: 'input',
      required: true,
      disabled: true,
      validator: (value = '') => validateName(value)
    },
    {
      label: 'Jenis Kelamin',
      name: 'gender',
      type: 'gender',
      required: true
    },
    ...(travelType === 'domestic' ? [{
      label: 'Kewarganegaraan',
      name: 'citizenship',
      type: 'select',
      required: true,
      options: [
        { value: 'WNI', label: 'Warga Negara Indonesia (WNI)' },
        { value: 'WNA', label: 'Warga Negara Asing (WNA)' }
      ]
    }] : []),
    {
      label: 'Tanggal Lahir',
      name: 'date_of_birth',
      type: 'date',
      required: true,
      validator: (value = '') => validateDateOfBirth(value, 'person', { travellingStartDate })
    },
    {
      label: getInsuredIdLabel({ travelType, values }),
      name: 'insured_id',
      type: 'input',
      required: true,
      validator: (value = '') => validateInsuredId(value, { travelType, values })
    },
    {
      label: getAddressLabel({ travelType, values }),
      name: 'address',
      type: 'input',
      required: true
    },
    {
      label: 'Nomor Ponsel',
      name: 'mobile_no',
      type: 'input',
      message: LANG_STRINGS.additionalInfoPhoneField,
      required: true,
      validator: (value = '') => validatePhoneNumber(value)
    },
    {
      label: 'Email',
      name: 'email',
      type: 'input',
      message: LANG_STRINGS.additionalInfoEmailField,
      required: true,
      validator: (value = '') => validateEmail(value)
    }
  ]
})

export const additionalPersonFormData = ({ travellingStartDate, travelType, policyType, values, allvalues, keyval }) => ({
  fieldData: [
    {
      label: getNameLabel({ travelType, values }),
      name: 'name',
      type: 'input',
      required: true,
      validator: (value = '') => validateName(value)
    },
    {
      label: 'Jenis Kelamin',
      name: 'gender',
      type: 'gender',
      required: true
    },
    ...(travelType === 'domestic' ? [{
      label: 'Kewarganegaraan',
      name: 'citizenship',
      type: 'select',
      required: true,
      options: [
        { value: 'WNI', label: 'Warga Negara Indonesia (WNI)' },
        { value: 'WNA', label: 'Warga Negara Asing (WNA)' }
      ]
    }] : []),
    {
      label: 'Tanggal Lahir',
      name: 'date_of_birth',
      type: 'date',
      required: true,
      validator: (value = '') => validateDateOfBirth(value, policyType === 'family' ? values.relation : 'group', { travellingStartDate, allvalues })
    },
    ...(policyType === 'family' ? [{
      label: 'Hubungan',
      name: 'relation',
      type: 'select',
      required: true,
      options: getFamilyRelationOptions({ travellingStartDate, values }),
      validator: (value = '') => validateFamilyRelation(value, { allvalues })
    }] : []),
    ...((travelType === 'international' || !(policyType === 'family' && values.relation === 'child') ) ? [{
      label: getInsuredIdLabel({ travelType, values }),
      name: 'insured_id',
      type: 'input',
      required: true,
      validator: (value = '') => validateInsuredId(value, { travelType, values })
    }] : []),
    ...(policyType === 'group' ? [
      {
        label: getAddressLabel({ travelType, values }),
        name: 'address',
        type: 'input',
        required: true
      },
      {
        label: 'Nomor Ponsel',
        name: 'mobile_no',
        type: 'input',
        message: LANG_STRINGS.additionalInfoPhoneField,
        required: true,
        validator: (value = '') => validatePhoneNumber(value)
      },
      {
        label: 'Email',
        name: 'email',
        type: 'input',
        message: LANG_STRINGS.additionalInfoEmailField,
        required: true,
        validator: (value = '') => validateEmail(value)
      }
    ] : [])
  ]
})
