import { useCallback, useEffect, useState } from 'react'
import moment from 'moment'
import { LANG_STRINGS } from '../../../../../lang'
import PersonDetails from './PersonDetails/personDetails'
import { TravelRegistrationWrapper, SubmitButton, ButtonWrapper } from './index.style'

const Registration = (props) => {
  const {
    travelType,
    policyType,
    totalPeople = 0,
    travellingStartDate,
    mainTravellerIntialValues = {},
    customerData,
    submitTravelRegistrationData,
    submitTravelRegistrationDraft,
  } = props

  const initializeFormValue = () => {
    const formVal = {
      person: {},
      additionalPerson: [],
    }
    return formVal
  }
  const [noOfFormValid, setNoOfFormValid] = useState(0)
  const [formValues, setFormValues] = useState(initializeFormValue)
  const constructAdditionalPerson = (inputObject, isFamily) => {
    const addKey = (items, relation) => {
      if (!Array.isArray(items)) return []
      return items.map((item) => {
        const newItem = { ...item }
        if (isFamily) {
          newItem.relation = relation
        }
        return newItem
      })
    }
    const additionalPerson = [
      ...addKey(inputObject.adults, 'spouse'),
      ...addKey(inputObject.kids, 'child'),
      ...addKey(inputObject.siblings, 'sibling'),
      ...addKey(inputObject.parents, 'parent'),
    ]
    return additionalPerson
  }

  useEffect(() => {
    const additionalPersons = constructAdditionalPerson(customerData, policyType === 'family')
    setFormValues((formVal) => {
      const newFormValues = {
        ...formVal,
        person: {
          ...formVal.person,
          ...mainTravellerIntialValues,
        },
        additionalPerson: additionalPersons,
      }
      return newFormValues
    })
  }, [mainTravellerIntialValues, customerData, policyType])

  const onSubmitButtonClickHandler = (e) => {
    e.stopPropagation()
    submitTravelRegistrationData(formValues)
  }

  const personChangeHandler = (name, value) => {
    setFormValues((formValues) => {
      const newFormValues = { ...formValues }
      newFormValues.person = {
        ...newFormValues.person,
        [name]: value,
      }
      return newFormValues
    })
  }

  const additionalPersonChangeHandler = (name, value, personNumber) => {
    const changeResult = { invalidChange: false }
    setFormValues((formValues) => {
      const newFormValues = { ...formValues }
      newFormValues.additionalPerson[personNumber] = {
        ...newFormValues.additionalPerson[personNumber],
        [name]: value,
      }

      if (
        (name === 'relation' && value === 'child') ||
        (name === 'date_of_birth' && moment(travellingStartDate).diff(value, 'years', true) < 18)
      ) {
        delete newFormValues.additionalPerson[personNumber]?.insured_id
      }
      return newFormValues
    })

    return changeResult
  }

  const formValidChangeHandler = (valid) => {
    if (valid) {
      setNoOfFormValid((noOfFormValid) => noOfFormValid + 1)
    } else {
      setNoOfFormValid((noOfFormValid) => noOfFormValid - 1)
    }
  }

  const renderAdditionalPerson = useCallback(() => {
    const children = []
    for (let i = 0; i < totalPeople; i++) {
      children.push(
        <PersonDetails
          key={i}
          type="additionalPerson"
          travelType={travelType}
          policyType={policyType}
          mainTravellerGender={formValues.person.gender}
          title={`${LANG_STRINGS.additionalInsured} ${i + 1}`}
          values={formValues.additionalPerson[i]}
          allvalues={formValues}
          keyval={i}
          formValidChangeHandler={formValidChangeHandler}
          onChange={(name, value) => additionalPersonChangeHandler(name, value, i)}
          submitTravelRegistrationDraft={submitTravelRegistrationDraft}
          formValues={formValues}
        />
      )
    }
    return children
  }, [formValues, travelType, totalPeople, policyType])

  return (
    <>
      <TravelRegistrationWrapper>
        <PersonDetails
          type="person"
          travelType={travelType}
          travellingStartDate={travellingStartDate}
          formValidChangeHandler={formValidChangeHandler}
          values={formValues.person}
          onChange={personChangeHandler}
          submitTravelRegistrationDraft={submitTravelRegistrationDraft}
          formValues={formValues}
        />
        {renderAdditionalPerson()}
      </TravelRegistrationWrapper>
      <ButtonWrapper>
        <SubmitButton onClick={onSubmitButtonClickHandler} disabled={noOfFormValid !== 0}>
          {LANG_STRINGS.send}
        </SubmitButton>
      </ButtonWrapper>
    </>
  )
}

export default Registration
