import { useState, useEffect } from 'react'
import { StyleContainer as Container, Content, FooterSection, FooterButton } from './index.styles'
import GuideSection from './GuideSection'
import UploadArea from './UploadArea'
import ErrorModal from './ErrorModal'
import { UPLOAD_STATUS, ERROR_TYPE, TEMPLATE_URLS } from './contants'
import { downloadFile } from '../../../../../../helpers/mitraUtils/mitra-utility'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { useUploadTravelApi } from './hooks/useUploadTravel'

const UploadTravel = ({
  onBackToManual = () => {},
  travelType = '',
  draftQuoteId,
  onUploadSuccess,
  onNextStep,
  passengerTotal,
}) => {
  const [status, setStatus] = useState(UPLOAD_STATUS.IDLE)
  const [file, setFile] = useState(null)
  const [errorModalVisible, setErrorModalVisible] = useState(false)
  const [errorType, setErrorType] = useState('full')
  const [loadingDownloadTemplate, setLoadingDownloadTemplate] = useState(false)

  const {
    loading,
    errorMessage,
    handleUploadTravel,
    isErrorPartial,
    errorPartialCount,
    isError,
    isSuccess,
    handleDownloadErrorData,
    handleResetError,
  } = useUploadTravelApi()

  const isValidExcelFile = (file) => file.name.endsWith('.xlsx') || file.name.endsWith('.xls')

  const handleFileSelect = (selectedFile) => {
    if (!isValidExcelFile(selectedFile)) {
      setErrorType(ERROR_TYPE.FULL)
      setErrorModalVisible(true)
      return
    }

    setFile(selectedFile)
    const formData = new FormData()
    formData.append('file', selectedFile)

    handleUploadTravel({ draftQuoteId, body: formData })
  }

  const handleDrop = (e) => {
    e.preventDefault()
    e.dataTransfer.files[0] && handleFileSelect(e.dataTransfer.files[0])
  }

  const handleDragOver = (e) => e.preventDefault()

  const handleDownloadTemplate = () => {
    setLoadingDownloadTemplate(true)
    try {
      const template = TEMPLATE_URLS[travelType]
      downloadFile(template.url, template.fileName)
    } catch (error) {
      ShowSnackbar.error({ text: error?.message ?? 'Unknown error occurred' })
    } finally {
      setLoadingDownloadTemplate(false)
    }
  }

  const handleUploadAgain = () => {
    setStatus(UPLOAD_STATUS.IDLE)
    setFile(null)
    setErrorModalVisible(false)
    handleResetError()
    // Reset or handle as needed
  }

  const handleDownloadError = () => {
    handleDownloadErrorData()
  }

  const handleSelanjutnya = () => onNextStep?.()

  // Handle upload state and response
  useEffect(() => {
    if (loading) {
      setStatus(UPLOAD_STATUS.LOADING)
    } else if (isSuccess) {
      setStatus(UPLOAD_STATUS.SUCCESS)
      ShowSnackbar.success({ visible: true, text: 'Upload berhasil' })
      // onUploadSuccess?.()
    } else if (isError) {
      if (isErrorPartial) {
        setStatus(UPLOAD_STATUS.ERROR_PARTIAL)
        setErrorType(ERROR_TYPE.PARTIAL)
        setErrorModalVisible(true)
      } else {
        setStatus(UPLOAD_STATUS.ERROR_FULL)
        setErrorType(ERROR_TYPE.FULL)
        setErrorModalVisible(true)
        ShowSnackbar.error({ visible: true, text: errorMessage })
      }
    } else {
      setStatus(UPLOAD_STATUS.IDLE)
    }
  }, [loading, isSuccess, isError, isErrorPartial, errorMessage, onUploadSuccess])

  // reset error data
  useEffect(() => {
    if (!errorModalVisible) {
      setErrorType(null)
      setErrorModalVisible(false)
      handleResetError()
    }
  }, [errorModalVisible])

  return (
    <Container>
      <Content>
        <GuideSection
          handleDownloadTemplate={handleDownloadTemplate}
          loading={loadingDownloadTemplate}
        />
        <UploadArea
          status={status}
          file={file}
          handleFileSelect={handleFileSelect}
          handleUploadAgain={handleUploadAgain}
          handleDrop={handleDrop}
          handleDragOver={handleDragOver}
        />
        <FooterSection>
          {passengerTotal > 10 && (
            <FooterButton onClick={onBackToManual} width="96px">
              Isi Manual
            </FooterButton>
          )}
          <FooterButton
            disabled={status !== UPLOAD_STATUS.SUCCESS}
            grow
            primary
            onClick={handleSelanjutnya}
          >
            Selanjutnya
          </FooterButton>
        </FooterSection>
      </Content>
      <ErrorModal
        errorModalVisible={errorModalVisible}
        errorType={errorType}
        setErrorModalVisible={setErrorModalVisible}
        handleUploadAgain={handleUploadAgain}
        handleDownloadError={handleDownloadError}
        errorMessage={errorMessage}
        isErrorPartial={isErrorPartial}
        errorPartialCount={errorPartialCount}
      />
    </Container>
  )
}

export default UploadTravel
