import { useEffect, useState, useRef } from 'react'
import {
  SelectInput,
  Option,
  SelectDrop,
  SelectIcon,
  SelectContainer,
  SelectOptionContainer,
  NoOptionContainer
} from './index.style'
import { Label } from '../Input/index.style'
import { LANG_STRINGS } from '../../../../lang'
import { ARROW_SELECTION } from '../../../../images'

function Select (props) {
  const { placeholder, options = [], onChange, value, error } = props
  const [isOptionContainerOpen, setOptionContainerOpen] = useState(false)
  const [filteredOptions] = useState(options)
  const [iValue, setIValue] = useState('')
  const ref = useRef(null)

  useEffect(() => {
    if (value) {
      const found = options.find((opt) => value === opt.value)
      if (!found) return
      setIValue(found.label || '')
    }
  }, [value])

  const openOptionContainer = (e) => {
    e.stopPropagation()
    e.preventDefault()
    setOptionContainerOpen(true)
  }

  const clickOptionHandler = (e, option) => {
    e.stopPropagation()
    const { label, disabled } = option
    if (disabled) return

    setOptionContainerOpen(false)
    const optionFound = options.find((opt) => opt.label?.toLowerCase() === (label.toLowerCase()))
    let changeResult
    if (!optionFound) {
      changeResult = onChange('')
    } else {
      changeResult = onChange(optionFound.value)
    }
    if (changeResult?.invalidChange) {
      setIValue('')
    } else {
      setIValue(label)
    }
  }

  const selectInputChangeHandler = (e) => {

    //   const { value } = e.target
    //   setIValue(value)
  }

  const handleClickOutside = (event) => {
    if (ref.current && !ref.current.contains(event.target)) {
      setIValue('')
      setOptionContainerOpen(false)
    }
  }

  useEffect(() => {
    document.addEventListener('click', handleClickOutside, false)

    return () => {
      document.removeEventListener('click', handleClickOutside, false)
    }
  }, [])

  // useEffect(() => {
  //   if (!iValue) {
  //     setFiltredOption(options)
  //     return
  //   }
  //   const newOptions = options.filter(({ label = '' }) => label.toLowerCase().includes(iValue.toLowerCase()))
  //   setFiltredOption(newOptions)
  // }, [
  //   iValue
  // ])

  useEffect(() => {
    if (!filteredOptions.length) {
      onChange('')
    }
  }, [
    iValue,
    filteredOptions
  ])

  return (
    <SelectContainer>
      <Label active={isOptionContainerOpen || iValue}>
        {placeholder}
      </Label>
      <SelectDrop error={error} onClick={openOptionContainer}>
        <SelectInput
          value={iValue}
          isOptionContainerOpen={isOptionContainerOpen}
          onChange={selectInputChangeHandler}
        />
        <SelectIcon src={ARROW_SELECTION} />
      </SelectDrop>
      {isOptionContainerOpen
        ? (
          <SelectOptionContainer ref={ref}>
            {filteredOptions.length
              ? filteredOptions.map((option) => {
                const { label, value, disabled } = option
                return (
                  <Option key={value} disabled={disabled} onClick={(e) => clickOptionHandler(e, option)}>
                    {label}
                  </Option>
                )
              })
              : <NoOptionContainer>{LANG_STRINGS.noOptions} </NoOptionContainer>}
          </SelectOptionContainer>
        )
        : null}
    </SelectContainer>
  )
}

export default Select
