import { useEffect, useMemo, useState } from 'react'
import CustomCollapse from '../../../../../../components/CustomCollapse'
import DynamicFormV2 from '../../../../../../components/DynamicFormV2'
import { LANG_STRINGS } from '../../../../../../lang'
import { personDetailsformData, additionalPersonFormData } from './formData'

function PersonDetails (props) {
  const {
    title = LANG_STRINGS.mainTraveller,
    type,
    onChange,
    values = {},
    formValidChangeHandler,
    travellingStartDate,
    travelType,
    policyType,
    allvalues,
    keyval,
    submitTravelRegistrationDraft,
    formValues
  } = props

  const [isFormValid, setFormValid] = useState(false)
  const [, setUserBlurred] = useState(false)

  useEffect(() => {
    formValidChangeHandler(isFormValid)
  }, [isFormValid])

  const formData = useMemo(() => {
    switch (type) {
      case 'additionalPerson':
        return additionalPersonFormData({ travellingStartDate, travelType, policyType, values, allvalues, keyval })
      case 'person':
      default:
        return personDetailsformData({ travellingStartDate, travelType, values })
    }
  }, [type, travellingStartDate, travelType, policyType, values, allvalues, keyval])

  useEffect(() => {
    let formValid = true
    const { fieldData = [] } = formData
    for (let i = 0; i < fieldData.length; i++) {
      const { name, required, validator } = fieldData[i]
      if (required && !values[name]) {
        formValid = false
        break
      }
      if (validator && validator(values[name])) {
        formValid = false
        break
      }
    }
    setFormValid(formValid)
  }, [values])

  return (
    <CustomCollapse isOpened hideBorders label={title}>
      <DynamicFormV2
        key={JSON.stringify(values.date_of_birth)}
        values={values}
        onChange={onChange}
        formData={formData}
        setUserBlurred={setUserBlurred}
        submitTravelRegistrationDraft={submitTravelRegistrationDraft}
        formValues={formValues}
      />
    </CustomCollapse>
  )
}

export default PersonDetails
