import {
  resetError,
  useErrorContextValue,
  useLoaderContextValue,
} from '@pasarpolis/common-react-hooks'
import { useUploadTravelPassenger } from '../../../../state/hooks/useTravelState'
import { downloadFile } from '../../../../../../../helpers/mitraUtils/mitra-utility'
import ShowSnackbar from '../../../../../../../components/ShowNotification'

export const useUploadTravelApi = () => {
  const [{ uploadTravelPassengerErrorData = null }, dispatchError] = useErrorContextValue()
  const [{ UPLOAD_TRAVEL_PASSENGER_LOADER = false }] = useLoaderContextValue()
  const [{ uploadTravelPassengerData = {} }, uploadTravelPassengerRequest] =
    useUploadTravelPassenger()

  const isError = Boolean(uploadTravelPassengerErrorData)
  const isSuccess = Boolean(uploadTravelPassengerData?.message)
  const isErrorPartial = Boolean(
    uploadTravelPassengerErrorData &&
      uploadTravelPassengerErrorData.detail != null &&
      typeof uploadTravelPassengerErrorData.detail === 'object' &&
      Object.keys(uploadTravelPassengerErrorData.detail).length > 0
  )
  const errorMessage = uploadTravelPassengerErrorData?.error || ''

  const errorPartialCount = {
    failed: uploadTravelPassengerErrorData?.detail?.count_failed || 0,
    success: uploadTravelPassengerErrorData?.detail?.count_success || 0,
    total:
      (uploadTravelPassengerErrorData?.detail?.count_failed || 0) +
      (uploadTravelPassengerErrorData?.detail?.count_success || 0),
  }

  const handleDownloadErrorData = () => {
    // if not have file error, download the source file
    const url =
      uploadTravelPassengerErrorData?.detail?.file_error_url ||
      uploadTravelPassengerErrorData?.detail?.file_source_url ||
      ''
    const fileName = url.substring(url.lastIndexOf('/') + 1) || 'error.xlxs'
    if (url) {
      downloadFile(url, fileName)
    } else {
      ShowSnackbar.error({ message: 'File not found' })
    }
  }

  const handleResetError = () => {
    dispatchError(
      resetError({
        uploadTravelPassengerErrorData: undefined,
      })
    )
  }

  return {
    loading: Boolean(UPLOAD_TRAVEL_PASSENGER_LOADER),
    errorMessage: errorMessage,
    data: uploadTravelPassengerData,
    isErrorPartial,
    isError,
    errorPartialCount,
    isSuccess,
    handleUploadTravel: uploadTravelPassengerRequest,
    handleDownloadErrorData,
    handleResetError,
  }
}
