import moment from 'moment'
import { regex } from '../../../../../../constants/regex'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../lang'

export const getNameLabel = ({ travelType, values }) => {
  switch (true) {
    case travelType === 'international':
      return 'Nama Sesuai Passport'
    case travelType === 'domestic' && values.citizenship === 'WNA':
      return 'Nama Sesuai KITAS/KITAP'
    case travelType === 'domestic' && values.citizenship === 'WNI':
    default:
      return 'Nama Sesuai KTP'
  }
}

export const validateName = (value) => {
  if (!regex.nameRegexAlphanumericButContainAtleastTwoCharacters.test(value)) {
    return LANG_STRINGS.nameShouldContain2CharacterAtleast
  }
  return null
}

export const validateDateOfBirth = (value, type, { travellingStartDate, allvalues }) => {
  const ageAtTravelYears = Math.ceil(moment(travellingStartDate).diff(value, 'years', true))
  const ageAtTravelMonths = Math.ceil(moment(travellingStartDate).diff(value, 'months', true))

  switch (type) {
    case 'person': {
      if (ageAtTravelYears < 17 || ageAtTravelYears > 84) return ERROR_LANG.ageShouldBeBetween17and84
      return null
    }
    case 'spouse': {
      if ((ageAtTravelYears < 17 || ageAtTravelYears > 84)) return ERROR_LANG.ageShouldBeBetween17and84
      return null
    }
    case 'child': {
      if (ageAtTravelYears <= 1 && ageAtTravelMonths < 3) return ERROR_LANG.ageShouldBeBetween3MonthsAnd18
      if (ageAtTravelYears > 18) return ERROR_LANG.ageShouldBeBetween3MonthsAnd18
      return null
    }
    case 'group': {
      if (ageAtTravelYears < 17 || ageAtTravelYears > 84) return ERROR_LANG.ageShouldBeBetween17and84
      return null
    }
    case undefined: // when user has not selected yet
    default: {
      const totalChild = allvalues?.additionalPerson.filter(x => x.relation === 'child').length
      const totalSpouse = allvalues?.additionalPerson.filter(x => x.relation === 'spouse').length

      if (totalChild > 3 && ageAtTravelYears <= 18) return ERROR_LANG.maxChildLimit
      if (totalSpouse > 1 && ageAtTravelYears >= 17) return ERROR_LANG.maxSpouseLimit
      return null
    }
  }
}

export const getFamilyRelationOptions = ({ travellingStartDate, values }) => {
  if (!values.date_of_birth) {
    return [
      { label: 'Pasangan', value: 'spouse', disabled: false },
      { label: 'Anak', value: 'child', disabled: false }
    ]
  }

  const ageAtTravelYears = Math.ceil(moment(travellingStartDate).diff(values.date_of_birth, 'years', true))
  return [
    { label: 'Pasangan', value: 'spouse', disabled: ageAtTravelYears < 17 },
    { label: 'Anak', value: 'child', disabled: ageAtTravelYears > 18 }
  ]
}

export const validateFamilyRelation = (value, { allvalues }) => {
  const totalChild = allvalues?.additionalPerson?.filter(x => x.relation === 'child').length
  const totalSpouse = allvalues?.additionalPerson?.filter(x => x.relation === 'spouse').length

  if (totalChild > 3 && value === 'child') return ERROR_LANG.maxChildLimit
  if (totalSpouse > 1 && value === 'spouse') return ERROR_LANG.maxSpouseLimit
  return null
}

export const getInsuredIdLabel = ({ travelType, values }) => {
  switch (true) {
    case travelType === 'international':
      return 'No. Passport'
    case travelType === 'domestic' && values.citizenship === 'WNA':
      return 'No. KITAS/KITAP'
    case travelType === 'domestic' && values.citizenship === 'WNI':
    default:
      return 'No. KTP'
  }
}

export const validateInsuredId = (value, { travelType, values }) => {
  switch (travelType) {
    case 'international': {
      if (!value) return LANG_STRINGS.required
      if (!regex.alphaNumeric.test(value)) return ERROR_LANG.passportCorrectError
      if (value.length < 6 || value.length > 9) return ERROR_LANG.passportCorrectError
      return null
    }
    case 'domestic': {
      if (!value) return LANG_STRINGS.required
      if (values.citizenship === 'WNI' && (!value || value.length !== 16 || isNaN(value))) {
        return ERROR_LANG.ktpError
      }
      if (values.citizenship === 'WNA' && (!value || value.length < 11 || value.length > 12 || !regex.alphaNumeric.test(value))) {
        return ERROR_LANG.ktpErrorBetween11And12
      }
      return null
    }
    default:
      return null
  }
}

export const getAddressLabel = ({ travelType, values }) => {
  switch (true) {
    case travelType === 'international':
      return 'Alamat Sesuai Passport'
    case travelType === 'domestic' && values.citizenship === 'WNA':
      return 'Alamat Sesuai Domisili'
    case travelType === 'domestic' && values.citizenship === 'WNI':
    default:
      return 'Alamat Sesuai KTP'
  }
}

export const validatePhoneNumber = (value) => {
  if (!(['+62', '62', '08'].some((pre) => value.startsWith(pre)))) return ERROR_LANG.phoneNumberNotStartsWith62
  if (value.startsWith('+62') && value.length > 15) return ERROR_LANG.max15DigitAllowed
  if (value.length > 14) return ERROR_LANG.max14DigitAllowed
  if (!regex.phoneRegex.test(value)) return ERROR_LANG.phoneNumberError
  return null
}

export const validateEmail = (value) => {
  if (!regex.emailRegex.test(value)) return ERROR_LANG.emailRequiredError
  return null
}
