import { useCallback, useEffect, useState } from 'react'
import Input from './components/Input'

import { ErrorText, FormItem, FormWrapper } from './dynamicFormV2.style'
import Gender from './components/Gender'
import Select from './components/Select'
import DatePicker from './components/DatePicker'

function DynamicFormV2 (props) {
  const {
    formData,
    onChange,
    values = {},
    ktpErrorMessage,
    setUserBlurred,
    submitTravelRegistrationDraft,
    formValues
  } = props
  const { fieldData } = formData

  useEffect(() => {
    setErrors((err) => ({
      ...err,
      insured_id: ktpErrorMessage
    }))
  }, [ktpErrorMessage])

  const [errors, setErrors] = useState({})

  const onChangeHandler = (name, value, validator) => {
    setUserBlurred(false)
    const changeResult = onChange(name, value)
    validateField(name, value, validator, changeResult)
    return changeResult
  }

  const onDateChangeHandler = (name, value, validator) => {
    onChange(name, value)
    validateField(name, value, validator)
    submitTravelRegistrationDraft(formValues)
  }

  const validateField = (name, value, validator, changeResult = {}) => {
    const changeResultInValid = changeResult?.invalidChange
    const changeResultMessage = changeResult?.validationMessage
    const validateMessage = (!changeResultInValid && validator) ? validator(value) : undefined

    const newErrors = { ...errors }
    newErrors[name] = changeResultMessage || validateMessage
    setErrors(newErrors)
  }

  const onBlurHandler = (name, value, validator) => {
    let newValue = value
    if (name === 'mobile_no') {
      newValue = newValue === '+62' ? '' : newValue
      onChange(name, newValue)
    }
    validateField(name, newValue, validator)
    setUserBlurred(true)
    submitTravelRegistrationDraft(formValues)
  }

  const citizenshipChangeHandler = useCallback(
    (name, value) => {
      onChange(name, value)
      setUserBlurred(true)
    },
    [setUserBlurred, onChange]
  )

  const onClickHandler = (name, value) => {
    if (name === 'mobile_no' && !value) {
      onChange(name, '+62' + value)
    }
  }

  const renderFieldItem = useCallback(
    (item) => {
      const { type, label, name, validator, options, disabled, message } = item
      if (name === 'citizenship') {
        return (
          <Select
            value={values[name]}
            placeholder={label}
            options={options}
            onChange={(value) => onChangeHandler(name, value, validator)}
            onBlur={(e) => onBlurHandler(name, e.target.value, validator)}
          />
        )
      }
      switch (type) {
        case 'input':
          return (
            <>
              <Input
                disabled={disabled}
                error={errors[name]}
                placeholder={label}
                value={values[name] || ''}
                onChange={(e) =>
                  onChangeHandler(name, e.target.value, validator)}
                onBlur={(e) => onBlurHandler(name, e.target.value, validator)}
                onClick={(e) => {
                  onClickHandler(name, values[name] || '')
                }}
              />
              {message ? (
                <div className='dynamic-form__info-wrapper'>
                  <svg
                    width='12'
                    height='12'
                    viewBox='0 0 12 12'
                    fill='none'
                    xmlns='http://www.w3.org/2000/svg'
                  >
                    <path
                      d='M1 6C1 7.32608 1.52678 8.59785 2.46447 9.53553C3.40215 10.4732 4.67392 11 6 11C7.32608 11 8.59785 10.4732 9.53553 9.53553C10.4732 8.59785 11 7.32608 11 6C11 4.67392 10.4732 3.40215 9.53553 2.46447C8.59785 1.52678 7.32608 1 6 1C4.67392 1 3.40215 1.52678 2.46447 2.46447C1.52678 3.40215 1 4.67392 1 6Z'
                      fill='white'
                      stroke='#333333'
                      stroke-linecap='round'
                      stroke-linejoin='round'
                    />
                    <path
                      d='M7.13627 8.27453H6.45446C6.3339 8.27453 6.21829 8.22664 6.13304 8.1414C6.0478 8.05616 5.99991 7.94054 5.99991 7.81999V5.22694C5.99991 5.16666 5.97597 5.10885 5.93334 5.06623C5.89072 5.02361 5.83291 4.99966 5.77264 4.99966H5.09082'
                      stroke='#333333'
                      stroke-linecap='round'
                      stroke-linejoin='round'
                    />
                    <path
                      d='M5.69658 2.96924C5.63665 2.96924 5.57806 2.98701 5.52823 3.02031C5.4784 3.05361 5.43956 3.10093 5.41662 3.1563C5.39369 3.21168 5.38768 3.2726 5.39938 3.33139C5.41107 3.39017 5.43993 3.44416 5.48231 3.48654C5.52469 3.52892 5.57868 3.55778 5.63747 3.56948C5.69625 3.58117 5.75718 3.57517 5.81255 3.55223C5.86792 3.5293 5.91525 3.49046 5.94855 3.44062C5.98184 3.39079 5.99962 3.3322 5.99962 3.27227C5.99962 3.1919 5.96769 3.11482 5.91086 3.05799C5.85403 3.00116 5.77695 2.96924 5.69658 2.96924Z'
                      fill='#333333'
                      stroke='#333333'
                      stroke-width='0.8'
                      stroke-linecap='round'
                      stroke-linejoin='round'
                    />
                  </svg>
                  <p className=''>{message}</p>
                </div>
              ) : (
                ''
              )}
            </>
          )
        case 'select':
          return (
            <Select
              value={values[name]}
              error={errors[name]}
              placeholder={label}
              options={options}
              onChange={(value) => onChangeHandler(name, value, validator)}
              onBlur={(e) => onBlurHandler(name, e.target.value, validator)}
            />
          )
        case 'gender':
          return (
            <Gender
              label={label}
              value={values[name]}
              onChange={(value) => onChangeHandler(name, value, validator)}
            />
          )
        case 'date':
          return (
            <DatePicker
              label={label}
              error={errors[name]}
              defaultValue={values[name]}
              selectionType='single'
              maxDate={new Date()}
              validator={(value) => validateField(name, value, validator)}
              onChange={(value) => onDateChangeHandler(name, value, validator)}
            />
          )
        default:
          return (
            <Input
              values={values[name]}
              error={errors[name]}
              placeholder={label}
              onChange={(e) => onChangeHandler(name, e.target.value, validator)}
              onBlur={(e) => onBlurHandler(name, e.target.value, validator)}
            />
          )
      }
    },
    [citizenshipChangeHandler, values, fieldData, errors]
  )

  return (
    <FormWrapper>
      {fieldData &&
        fieldData.map((item) => {
          const { name } = item
          return (
            <FormItem key={item.name}>
              {renderFieldItem(item)}
              {errors[name] ? <ErrorText>{errors[name]}</ErrorText> : null}
            </FormItem>
          )
        })}
    </FormWrapper>
  )
}

export default DynamicFormV2
